package com.bbms.web;

import com.bbms.domain.*;
import com.bbms.repo.*;
import com.bbms.service.*;
import jakarta.validation.Valid;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.beans.factory.ObjectProvider;
import com.bbms.config.TrainingClock;
import org.springframework.http.HttpStatus;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.*;
import java.util.*;

@Controller
public class WebController {
    private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(WebController.class);
    static final List<String> COMPONENTS=List.of("Whole Blood","Red Cells","Platelets","Plasma");
    private final UserRepository users; private final BloodUnitRepository units; private final BloodRequestRepository requests;
    private final DonationAppointmentRepository appointments; private final DonationRecordRepository donations; private final BloodIssueRepository issues;
    private final InventoryMovementRepository movements; private final BloodRequestEventRepository requestEvents; private final DonationAppointmentEventRepository appointmentEvents; private final DonationReminderRepository reminders;
    private final AccountService accounts; private final BloodBankService bank; private final BloodRequestWorkflowService workflow; private final DonationAppointmentService appointmentService; private final InventoryReceiptService inventoryReceipts; private final DonationInventoryReceiptService donationInventoryReceipts; private final InventoryBatchStatusService inventoryBatchStatus; private final TargetInventoryService targetInventory;
    private final Clock clock;
    private final ObjectProvider<TrainingClock> trainingClock;
    private final ObjectProvider<TrainingDonationWorkflowService> trainingDonationWorkflow;
    @Value("${bbms.training.mode:false}") private boolean trainingMode;
    @Value("${bbms.inventory.target-initializer.enabled:false}") private boolean targetInitializerEnabled;
    @Value("${server.port:8080}") private String serverPort;
    @Value("${bbms.presentation.expected-database:}") private String presentationDatabase;

    public WebController(UserRepository users,BloodUnitRepository units,BloodRequestRepository requests,DonationAppointmentRepository appointments,
                         DonationRecordRepository donations,BloodIssueRepository issues,InventoryMovementRepository movements,
                         BloodRequestEventRepository requestEvents,DonationAppointmentEventRepository appointmentEvents,DonationReminderRepository reminders,
                         AccountService accounts,BloodBankService bank,BloodRequestWorkflowService workflow,DonationAppointmentService appointmentService,InventoryReceiptService inventoryReceipts,DonationInventoryReceiptService donationInventoryReceipts,InventoryBatchStatusService inventoryBatchStatus,TargetInventoryService targetInventory,Clock clock,ObjectProvider<TrainingClock> trainingClock,ObjectProvider<TrainingDonationWorkflowService> trainingDonationWorkflow){
        this.users=users;this.units=units;this.requests=requests;this.appointments=appointments;this.donations=donations;this.issues=issues;
        this.movements=movements;this.requestEvents=requestEvents;this.appointmentEvents=appointmentEvents;this.reminders=reminders;
        this.accounts=accounts;this.bank=bank;this.workflow=workflow;this.appointmentService=appointmentService;this.inventoryReceipts=inventoryReceipts;this.donationInventoryReceipts=donationInventoryReceipts;this.inventoryBatchStatus=inventoryBatchStatus;this.targetInventory=targetInventory;this.clock=clock;this.trainingClock=trainingClock;this.trainingDonationWorkflow=trainingDonationWorkflow;
    }
    private LocalDate today(){return LocalDate.now(clock);}
    private LocalTime nowTime(){return LocalTime.now(clock);}
    private boolean visible(boolean synthetic){return trainingMode || !synthetic;}
    private boolean targetSample(BloodUnit unit){return unit.isDemoData()&&unit.getDemoKey()!=null&&unit.getDemoKey().startsWith(TargetInventoryService.SAMPLE_PREFIX);}
    private boolean visibleInventoryBatch(BloodUnit unit){return trainingMode||!unit.isDemoData()||targetSample(unit);}
    private User me(Authentication auth){return users.findByEmailIgnoreCase(auth.getName()).orElseThrow();}
    @ModelAttribute("groups") List<String> groups(){return BloodBankService.GROUPS;}
    @ModelAttribute("components") List<String> components(){return COMPONENTS;}
    @ModelAttribute("trainingMode") boolean trainingMode(){return trainingMode;}
    @ModelAttribute("trainingNow") LocalDateTime trainingNow(){return trainingMode?LocalDateTime.now(clock):null;}
    private boolean targetInitializerAvailable(){return targetInitializerEnabled&&!trainingMode&&"8080".equals(serverPort)&&(presentationDatabase==null||presentationDatabase.isBlank());}
    @ModelAttribute("targetInitializerEnabled") boolean targetInitializerEnabled(){return targetInitializerAvailable();}
    @ModelAttribute("currentDate") LocalDate currentDate(){return today();}

    @GetMapping("/") public String home(Model m){List<BloodUnit> real=units.findAllByOrderByExpiryDateAsc().stream().filter(u->visible(u.isDemoData())&&u.getStatus().equals("RELEASED")&&!u.getExpiryDate().isBefore(today())).toList();m.addAttribute("inventory",real);Map<String,Long> stock=new LinkedHashMap<>();for(String g:BloodBankService.GROUPS)stock.put(g,units.stockBySource(g,"Whole Blood",today(),trainingMode));m.addAttribute("stock",stock);return "home";}
    @GetMapping("/login") public String login(Authentication auth){if(auth!=null&&auth.isAuthenticated()&&!(auth instanceof org.springframework.security.authentication.AnonymousAuthenticationToken))return "redirect:/dashboard";return "login";}
    @GetMapping("/register") public String register(Model m){m.addAttribute("registrationForm",new RegistrationForm());return "register";}
    @PostMapping("/register") public String register(@Valid @ModelAttribute RegistrationForm form,BindingResult result){
        if("HOSPITAL".equals(form.getRole())&&(form.getOrganization()==null||form.getOrganization().isBlank()))result.rejectValue("organization","required","Enter your hospital or organization name.");
        if("DONOR".equals(form.getRole())&&(form.getBloodGroup()==null||!BloodBankService.GROUPS.contains(form.getBloodGroup())))result.rejectValue("bloodGroup","required","Choose your blood group.");
        if(result.hasErrors())return "register";
        try{accounts.register(form.getName(),form.getEmail(),form.getPassword(),form.getRole(),form.getOrganization(),form.getPhone(),form.getBloodGroup());return "redirect:/login?registered";}
        catch(IllegalArgumentException e){result.reject("registration",e.getMessage());return "register";}
    }
    @GetMapping("/dashboard") public String dashboard(Authentication auth){return "redirect:/"+me(auth).getRole().toLowerCase(Locale.ROOT)+"/dashboard";}

    @GetMapping("/admin/dashboard") public String admin(Model m){List<BloodUnit> stock=units.findAllByOrderByExpiryDateAsc().stream().filter(u->visible(u.isDemoData())).toList();long eligible=stock.stream().filter(u->u.getStatus().equals("RELEASED")&&!u.getExpiryDate().isBefore(today())).mapToLong(BloodUnit::getQuantity).sum();long low=0;for(String g:BloodBankService.GROUPS)for(String c:COMPONENTS)if(units.stockBySource(g,c,today(),trainingMode)<5)low++;m.addAttribute("eligibleTotal",eligible);m.addAttribute("lowStockGroups",low);m.addAttribute("nearExpiryCount",stock.stream().filter(u->u.getStatus().equals("RELEASED")&&!u.getExpiryDate().isBefore(today())&&!u.getExpiryDate().isAfter(today().plusDays(30))).count());m.addAttribute("donors",users.findByRoleOrderByCreatedAtDesc("DONOR").stream().filter(u->visible(u.isDemoData())).count());m.addAttribute("hospitals",users.findByRoleOrderByCreatedAtDesc("HOSPITAL").stream().filter(u->visible(u.isDemoData())).count());m.addAttribute("pending",requests.findAllByOrderByCreatedAtDesc().stream().filter(r->visible(r.isDemoData())&&"PENDING".equals(r.getStatus())).count());m.addAttribute("issues",issues.findAll().stream().filter(i->visible(i.isDemoData())).count());m.addAttribute("donationCount",donations.findAllByOrderByDonationDateDesc().stream().filter(d->visible(d.isDemoData())).count());List<BloodRequest> queue=requests.findAllByOrderByCreatedAtDesc().stream().filter(r->visible(r.isDemoData())&&"PENDING".equals(r.getStatus())).sorted(Comparator.comparingInt((BloodRequest r)->r.getPriorityLabel().equals("Urgent")?0:1).thenComparing(BloodRequest::getCreatedAt)).limit(8).toList();m.addAttribute("requests",queue);m.addAttribute("appointments",appointments.findAllByOrderByRequestedDateAsc().stream().filter(a->visible(a.isDemoData())&&!a.getRequestedDate().isBefore(today())&&List.of("PENDING","CONFIRMED").contains(a.getStatus())).limit(8).toList());return "admin";}

    @GetMapping("/admin/inventory") public String inventory(@RequestParam(required=false) String group,@RequestParam(required=false) String component,@RequestParam(required=false) String status,@RequestParam(required=false) String expiry,@RequestParam(defaultValue="false") boolean showZeroStock,Model m){
        LocalDate today=today();List<BloodUnit> all=units.findAllByOrderByExpiryDateAsc().stream().filter(this::visibleInventoryBatch).toList();
        List<BloodUnit> filtered=all.stream().filter(u->(group==null||group.isBlank()||group.equals(u.getBloodGroup()))&&(component==null||component.isBlank()||component.equals(u.getComponent()))&&(status==null||status.isBlank()||status.equals(u.getStatus()))&&( "expired".equals(expiry)?u.getExpiryDate().isBefore(today):"next30".equals(expiry)?!u.getExpiryDate().isBefore(today)&&!u.getExpiryDate().isAfter(today.plusDays(30)):true)).toList();
        Map<String,Long> stock=new LinkedHashMap<>();for(String c:COMPONENTS)for(String g:BloodBankService.GROUPS)stock.put(g+" · "+c,units.stockBySource(g,c,today,trainingMode));
        long eligible=stock.values().stream().mapToLong(Long::longValue).sum();long near=all.stream().filter(u->u.getStatus().equals("RELEASED")&&!u.getExpiryDate().isBefore(today)&&!u.getExpiryDate().isAfter(today.plusDays(30))).count();long pending=requests.findAllByOrderByCreatedAtDesc().stream().filter(r->visible(r.isDemoData())&&"PENDING".equals(r.getStatus())).count();
        m.addAttribute("units",filtered);m.addAttribute("stock",stock);m.addAttribute("eligibleTotal",eligible);m.addAttribute("lowStockCount",stock.values().stream().filter(v->v<5).count());m.addAttribute("nearExpiryCount",near);m.addAttribute("pendingCount",pending);m.addAttribute("selectedEligible",group!=null&&!group.isBlank()&&component!=null&&!component.isBlank()?units.stockBySource(group,component,today,trainingMode):null);m.addAttribute("showZeroStock",showZeroStock);m.addAttribute("selectedGroup",group);m.addAttribute("selectedComponent",component);m.addAttribute("selectedStatus",status);m.addAttribute("selectedExpiry",expiry);m.addAttribute("targetSamples",all.stream().filter(this::targetSample).toList());m.addAttribute("targetPlan",targetInventory.targetPlan());return "inventory";
    }

    @GetMapping("/admin/inventory/{id}") public String inventoryDetail(@PathVariable Long id,Model m){BloodUnit unit=units.findById(id).filter(this::visibleInventoryBatch).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));m.addAttribute("unit",unit);m.addAttribute("targetSample",targetSample(unit));m.addAttribute("movements",movements.findByUnitIdOrderByOccurredAtDesc(id).stream().filter(v->trainingMode||!v.isDemoData()||targetSample(unit)).toList());return "inventory-detail";}

    @PostMapping("/admin/inventory") public String addUnit(Authentication auth,@RequestParam String batchId,@RequestParam String bloodGroup,@RequestParam String component,@RequestParam LocalDate collectionDate,@RequestParam LocalDate expiryDate,@RequestParam String status,@RequestParam int quantity,@RequestParam String receiptReference,RedirectAttributes ra){
        try{List<String> allowedStatuses=trainingMode?List.of("RELEASED","QUARANTINED","TESTING"):List.of("QUARANTINED","TESTING");if(batchId==null||bloodGroup==null||component==null||status==null||collectionDate==null||expiryDate==null||!BloodBankService.GROUPS.contains(bloodGroup)||!COMPONENTS.contains(component)||!allowedStatuses.contains(status)||quantity<1||batchId.isBlank()||batchId.length()>80||collectionDate.isAfter(today())||!expiryDate.isAfter(collectionDate))throw new IllegalArgumentException("Check batch ID, group, component, status, quantity, and dates. Operational receipts must begin in testing or quarantine.");BloodUnit u=new BloodUnit();u.setBatchId(batchId.trim());u.setBloodGroup(bloodGroup);u.setComponent(component);u.setCollectionDate(collectionDate);u.setExpiryDate(expiryDate);u.setStatus(status);u.setQuantity(quantity);inventoryReceipts.receive(u,receiptReference,auth.getName());ra.addFlashAttribute("success","Batch receipt recorded with its movement reference.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/inventory";
    }

    @PostMapping("/admin/inventory/target-samples/initialize") public String initializeTargetSamples(Authentication auth,RedirectAttributes ra){if(!targetInitializerAvailable())throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{int created=targetInventory.initializeTargetSamples(auth.getName());ra.addFlashAttribute("success",created==0?"Target sample batches already match the plan; no records changed.":created+" unverified, quarantined sample batches were recorded. They are not operational stock.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/inventory";}

    @PostMapping("/admin/inventory/{id}/testing") public String beginInventoryBatchTesting(@PathVariable Long id,@RequestParam String testingReference,Authentication auth,RedirectAttributes ra){if(trainingMode)throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{inventoryBatchStatus.beginTesting(id,testingReference,auth.getName());ra.addFlashAttribute("success","Quarantine clearance and testing transition recorded.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/inventory/"+id;}
    @PostMapping("/admin/inventory/{id}/release") public String releaseInventoryBatch(@PathVariable Long id,@RequestParam String releaseDecisionReference,Authentication auth,RedirectAttributes ra){if(trainingMode)throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{inventoryBatchStatus.release(id,releaseDecisionReference,auth.getName());ra.addFlashAttribute("success","Batch release decision recorded with its audit movement.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/inventory/"+id;}

    @GetMapping("/admin/accounts") public String accounts(Model m){m.addAttribute("donorAccounts",users.findByRoleOrderByCreatedAtDesc("DONOR").stream().filter(u->visible(u.isDemoData())).toList());m.addAttribute("hospitalAccounts",users.findByRoleOrderByCreatedAtDesc("HOSPITAL").stream().filter(u->visible(u.isDemoData())).toList());return "accounts";}
    @PostMapping("/admin/accounts/{id}/toggle") public String toggleAccount(@PathVariable Long id,RedirectAttributes ra){User u=users.findById(id).orElseThrow();if(u.isDemoData()&&!trainingMode)throw new IllegalArgumentException("Archived placeholder accounts are read-only.");if(!List.of("DONOR","HOSPITAL").contains(u.getRole()))throw new IllegalArgumentException("Only donor and requester accounts can be managed here.");u.toggleEnabled();users.save(u);ra.addFlashAttribute("success","Account "+(u.isEnabled()?"enabled":"disabled")+".");return "redirect:/admin/accounts";}

    @GetMapping("/admin/donations") public String donationRecords(Model m){m.addAttribute("records",donations.findAllByOrderByDonationDateDesc().stream().filter(d->visible(d.isDemoData())).toList());m.addAttribute("donorAccounts",users.findByRoleOrderByCreatedAtDesc("DONOR").stream().filter(u->visible(u.isDemoData())&&u.getBloodGroup()!=null).toList());m.addAttribute("attendedAppointments",appointments.findAllByOrderByRequestedDateAsc().stream().filter(a->isDonationEligibleAppointment(a,today(),trainingMode)&&!donations.existsByAppointment(a)).toList());m.addAttribute("appointmentQueue",appointments.findAllByOrderByRequestedDateAsc().stream().filter(a->visible(a.isDemoData())&&!a.getRequestedDate().isBefore(today())&&List.of("PENDING","CONFIRMED").contains(a.getStatus())).toList());return "donations";}
    static boolean isDonationEligibleAppointment(DonationAppointment appointment,LocalDate today){return isDonationEligibleAppointment(appointment,today,false);}
    static boolean isDonationEligibleAppointment(DonationAppointment appointment,LocalDate today,boolean trainingMode){return (trainingMode||!appointment.isDemoData())&&"ATTENDED".equals(appointment.getStatus())&&!appointment.getRequestedDate().isAfter(today);}
    @PostMapping("/admin/donations") public String addDonation(Authentication auth,@RequestParam Long donorId,@RequestParam(required=false) Long appointmentId,@RequestParam String component,@RequestParam int units,@RequestParam LocalDate donationDate,@RequestParam(defaultValue="") String inventoryBatchId,RedirectAttributes ra){try{User donor=users.findById(donorId).filter(u->visible(u.isDemoData())).orElseThrow(()->new IllegalArgumentException("Choose an active donor account."));if(!"DONOR".equals(donor.getRole())||donor.getBloodGroup()==null)throw new IllegalArgumentException("Select a donor with a recorded blood group.");if(!COMPONENTS.contains(component)||units<1||units>10||donationDate.isAfter(today()))throw new IllegalArgumentException("Check component, units (1–10), and donation date.");appointmentService.recordDonation(appointmentId,donor,component,units,donationDate,inventoryBatchId.isBlank()?null:inventoryBatchId.trim(),auth.getName());ra.addFlashAttribute("success","Donation record saved. Testing and release are tracked separately.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/donations";}
    @PostMapping("/admin/donations/{id}/testing") public String testing(@PathVariable Long id,@RequestParam String status,RedirectAttributes ra){DonationRecord d=donations.findById(id).filter(record->visible(record.isDemoData())).orElseThrow();if(trainingMode&&d.isDemoData()){ra.addFlashAttribute("error","Use the clearly labelled training simulation controls for synthetic records.");return "redirect:/admin/donations";}if(!List.of("COLLECTED","TESTING","REJECTED").contains(status)||!allowedTesting(d.getTestingStatus(),status)){ra.addFlashAttribute("error","That testing status transition is not allowed. Release is recorded only with the donation receipt.");return "redirect:/admin/donations";}d.setTestingStatus(status);donations.save(d);ra.addFlashAttribute("success","Donation testing status updated. Inventory is not created automatically.");return "redirect:/admin/donations";}
    @PostMapping("/admin/donations/{id}/receive") public String receiveReleasedDonation(@PathVariable Long id,@RequestParam String batchId,@RequestParam LocalDate expiryDate,@RequestParam String releaseDecisionReference,@RequestParam String physicalReceiptReference,Authentication auth,RedirectAttributes ra){if(trainingMode)throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{donationInventoryReceipts.receiveReleasedDonation(id,batchId,expiryDate,releaseDecisionReference,physicalReceiptReference,auth.getName());ra.addFlashAttribute("success","Verified donation release and physical receipt were recorded and linked atomically.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/donations";}
    @PostMapping("/admin/training/donations/{id}/simulate-screening") public String simulateTrainingScreening(@PathVariable Long id,RedirectAttributes ra){if(!trainingMode)throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{trainingDonationWorkflow.getObject().simulateScreeningPass(id);ra.addFlashAttribute("success","TRAINING SIMULATION: synthetic screening pass recorded; this is not a medical test.");}catch(Exception ex){ra.addFlashAttribute("error",ex.getMessage());}return "redirect:/admin/donations";}
    @PostMapping("/admin/training/donations/{id}/receive") public String receiveTrainingDonation(@PathVariable Long id,@RequestParam String batchId,Authentication auth,RedirectAttributes ra){if(!trainingMode)throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{trainingDonationWorkflow.getObject().receiveAfterSimulatedPass(id,batchId,auth.getName());ra.addFlashAttribute("success","Synthetic training units were received; not clinical stock.");}catch(Exception ex){ra.addFlashAttribute("error",ex.getMessage());}return "redirect:/admin/donations";}
    @PostMapping("/admin/training/clock/advance") public String advanceTrainingClock(@RequestParam LocalDate date,@RequestParam LocalTime time,RedirectAttributes ra){if(!trainingMode)throw new ResponseStatusException(HttpStatus.NOT_FOUND);try{LocalDateTime target=LocalDateTime.of(date,time);if(target.isAfter(LocalDateTime.now(clock).plusDays(365)))throw new IllegalArgumentException("Training clock may advance at most one year.");trainingClock.getObject().advanceTo(target);ra.addFlashAttribute("success","Training simulation clock advanced to "+target+"; real system time was not changed.");}catch(Exception ex){ra.addFlashAttribute("error",ex.getMessage());}return "redirect:/admin/donations";}
    private boolean allowedTesting(String from,String to){return from.equals(to)||switch(from){case "COLLECTED"->List.of("TESTING","REJECTED").contains(to);case "TESTING"->List.of("REJECTED").contains(to);default->false;};}
    @GetMapping("/admin/reports") public String reports(Model m){List<BloodUnit> all=units.findAllByOrderByExpiryDateAsc().stream().filter(u->visible(u.isDemoData())).toList();Map<String,Long> stock=new TreeMap<>();for(String g:BloodBankService.GROUPS)for(String c:COMPONENTS)stock.put(g+" · "+c,units.stockBySource(g,c,today(),trainingMode));List<DonationRecord> donationRecords=donations.findAllByOrderByDonationDateDesc().stream().filter(d->visible(d.isDemoData())).toList();List<BloodRequest> requestRows=requests.findAllByOrderByCreatedAtDesc().stream().filter(r->visible(r.isDemoData())).toList();m.addAttribute("stock",stock);m.addAttribute("donationRecords",donationRecords.stream().limit(10).toList());m.addAttribute("donationCount",donationRecords.size());m.addAttribute("issuedCount",issues.findAll().stream().filter(i->visible(i.isDemoData())).count());m.addAttribute("requestCount",requestRows.size());m.addAttribute("pendingCount",requestRows.stream().filter(r->"PENDING".equals(r.getStatus())).count());m.addAttribute("nearExpiryCount",all.stream().filter(u->u.getStatus().equals("RELEASED")&&!u.getExpiryDate().isBefore(today())&&!u.getExpiryDate().isAfter(today().plusDays(30))).count());return "reports";}

    @GetMapping("/admin/requests") public String adminRequests(Model m){List<BloodRequest> list=requests.findAllByOrderByCreatedAtDesc().stream().filter(r->visible(r.isDemoData())).toList();m.addAttribute("requests",list);Map<Long,List<BloodRequestEvent>> history=new HashMap<>();Map<Long,Long> eligible=new HashMap<>();for(BloodRequest r:list)eligible.put(r.getId(),units.stockBySource(r.getBloodGroup(),r.getComponent(),today(),r.isDemoData()));if(!list.isEmpty())for(BloodRequestEvent e:requestEvents.findForRequests(list.stream().map(BloodRequest::getId).toList()))if(visible(e.isDemoData()))history.computeIfAbsent(e.getRequest().getId(),k->new ArrayList<>()).add(e);m.addAttribute("history",history);m.addAttribute("eligible",eligible);return "requests";}

    @PostMapping("/admin/requests/{id}/status") public String requestStatus(Authentication auth,@PathVariable Long id,@RequestParam String status,@RequestParam String reason,RedirectAttributes ra){try{workflow.review(id,status,reason,auth.getName());ra.addFlashAttribute("success","Request updated to "+status.toLowerCase(Locale.ROOT)+".");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/requests";}
    @PostMapping("/admin/requests/{id}/issue") public String issue(Authentication auth,@PathVariable Long id,RedirectAttributes ra){try{bank.issue(id,auth.getName());ra.addFlashAttribute("success","Blood issued and inventory updated.");}catch(Exception e){log.error("Blood issue transaction failed for request {}",id,e);ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/requests";}
    @PostMapping("/admin/appointments/{id}/status") public String appointmentStatus(Authentication auth,@PathVariable Long id,@RequestParam String status,@RequestParam(defaultValue="") String detail,RedirectAttributes ra){try{DonationAppointment appointment=appointments.findById(id).filter(item->visible(item.isDemoData())).orElseThrow();appointmentService.updateStatus(appointment.getId(),status,detail,auth.getName());ra.addFlashAttribute("success","Appointment updated.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/admin/donations";}

    private List<DonationAppointment> donorAppointments(User donor){return appointments.findByDonorOrderByRequestedDateDesc(donor).stream().filter(a->visible(a.isDemoData())).toList();}
    private Map<Long,List<DonationAppointmentEvent>> donorAppointmentHistory(List<DonationAppointment> list){
        Map<Long,List<DonationAppointmentEvent>> history=new HashMap<>();
        if(!list.isEmpty())for(DonationAppointmentEvent event:appointmentEvents.findForAppointments(list.stream().map(DonationAppointment::getId).toList()))history.computeIfAbsent(event.getAppointment().getId(),key->new ArrayList<>()).add(event);
        return history;
    }
    private List<DonationReminder> donorReminders(List<DonationAppointment> list){return list.stream().flatMap(a->reminders.findByAppointmentOrderByDueAtAsc(a).stream()).filter(r->List.of("DUE","SCHEDULED").contains(r.getStatus())).toList();}
    private void addDonorWorkspace(Model m,User donor,List<DonationAppointment> donorAppointments){
        m.addAttribute("donor",donor);m.addAttribute("appointments",donorAppointments);m.addAttribute("history",donorAppointmentHistory(donorAppointments));
        m.addAttribute("donationRecordedAppointmentIds",appointmentService.recordedAppointmentIds(donor,donorAppointments));
        m.addAttribute("upcomingReminders",donorReminders(donorAppointments));m.addAttribute("today",today());
    }
    @GetMapping("/donor/dashboard") public String donor(Authentication auth,Model m){
        User donor=me(auth);List<DonationAppointment> donorAppointments=donorAppointments(donor);
        DonationAppointment next=donorAppointments.stream().filter(a->(!a.getRequestedDate().isBefore(today()))&&(!a.getRequestedDate().equals(today())||a.getRequestedTime()==null||a.getRequestedTime().isAfter(nowTime()))&&List.of("PENDING","CONFIRMED").contains(a.getStatus())).min(Comparator.comparing(DonationAppointment::getRequestedDate).thenComparing(a->a.getRequestedTime()==null?LocalTime.MAX:a.getRequestedTime())).orElse(null);
        List<DonationRecord> records=donations.findByDonorOrderByDonationDateDesc(donor).stream().filter(d->visible(d.isDemoData())).toList();
        m.addAttribute("donor",donor);m.addAttribute("nextAppointment",next);m.addAttribute("nextAppointmentAction",next==null?"Choose a date and time to request an appointment.":"PENDING".equals(next.getStatus())?"Your request is waiting for the blood bank to confirm.":"Your appointment is confirmed. Review the time and location.");
        m.addAttribute("donationCount",records.size());m.addAttribute("recentDonations",records.stream().limit(3).toList());return "donor";
    }
    @GetMapping("/donor/appointments") public String donorAppointmentsPage(Authentication auth,Model m){User donor=me(auth);addDonorWorkspace(m,donor,donorAppointments(donor));return "donor-appointments";}
    @GetMapping("/donor/history") public String donorHistory(Authentication auth,Model m){User donor=me(auth);m.addAttribute("donor",donor);m.addAttribute("donations",donations.findByDonorOrderByDonationDateDesc(donor).stream().filter(d->visible(d.isDemoData())).toList());return "donor-history";}
    @PostMapping("/donor/appointments") public String appointment(Authentication auth,@RequestParam LocalDate requestedDate,@RequestParam(required=false) LocalTime requestedTime,@RequestParam String location,@RequestParam(defaultValue="false") boolean reminder3Days,@RequestParam(defaultValue="false") boolean reminder1Day,@RequestParam(defaultValue="false") boolean reminderDayOf,RedirectAttributes ra){try{appointmentService.request(me(auth),requestedDate,requestedTime,location,reminder3Days,reminder1Day,reminderDayOf,auth.getName());ra.addFlashAttribute("success","Appointment request submitted. Reminders are in-app only.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/donor/appointments";}
    @PostMapping("/donor/appointments/{id}/cancel") public String cancelAppointment(Authentication auth,@PathVariable Long id,RedirectAttributes ra){try{DonationAppointment a=appointments.findById(id).orElseThrow();if(!a.getDonor().getId().equals(me(auth).getId()))throw new IllegalArgumentException("Appointment not found.");appointmentService.updateStatus(id,"CANCELLED","Cancelled by donor.",auth.getName());ra.addFlashAttribute("success","Appointment cancelled.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/donor/appointments";}
    @PostMapping("/donor/appointments/{id}/reschedule") public String reschedule(Authentication auth,@PathVariable Long id,@RequestParam LocalDate requestedDate,@RequestParam LocalTime requestedTime,@RequestParam String location,RedirectAttributes ra){try{appointmentService.reschedule(id,me(auth),requestedDate,requestedTime,location,auth.getName());ra.addFlashAttribute("success","Appointment rescheduled. Bank confirmation is required again.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/donor/appointments";}

    @GetMapping("/hospital/dashboard") public String hospital(Authentication auth,Model m){List<BloodRequest> list=requests.findByRequesterOrderByCreatedAtDesc(me(auth)).stream().filter(r->visible(r.isDemoData())).toList();m.addAttribute("requests",list);Map<Long,List<BloodRequestEvent>> history=new HashMap<>();if(!list.isEmpty())for(BloodRequestEvent e:requestEvents.findForRequests(list.stream().map(BloodRequest::getId).toList()))if(visible(e.isDemoData()))history.computeIfAbsent(e.getRequest().getId(),k->new ArrayList<>()).add(e);m.addAttribute("history",history);Map<Long,Long> eligible=new HashMap<>();for(BloodRequest r:list)eligible.put(r.getId(),units.stockBySource(r.getBloodGroup(),r.getComponent(),today(),r.isDemoData()));m.addAttribute("eligible",eligible);return "hospital";}

    @PostMapping("/hospital/requests") public String request(Authentication auth,@RequestParam String bloodGroup,@RequestParam String component,@RequestParam int quantity,@RequestParam String urgency,@RequestParam String patientReference,@RequestParam(defaultValue="") String notes,@RequestParam(required=false) LocalDate requestDate,RedirectAttributes ra){try{workflow.submit(me(auth),bloodGroup,component,quantity,urgency,patientReference,notes,requestDate==null?today():requestDate,auth.getName());ra.addFlashAttribute("success","Blood request submitted for review.");}catch(Exception e){ra.addFlashAttribute("error",e.getMessage());}return "redirect:/hospital/dashboard";}

    @GetMapping({"/donor/profile","/hospital/profile"}) public String profile(Authentication auth,Model m){m.addAttribute("profile",me(auth));return "profile";}
    @PostMapping({"/donor/profile","/hospital/profile"}) public String saveProfile(Authentication auth,@RequestParam String name,@RequestParam(defaultValue="") String organization,@RequestParam(defaultValue="") String phone,@RequestParam(defaultValue="") String bloodGroup,RedirectAttributes ra){User u=me(auth);if(name.isBlank()||name.length()>100||phone.length()>40||(u.getRole().equals("HOSPITAL")&&(organization.isBlank()||organization.length()>150))||(u.getRole().equals("DONOR")&&!BloodBankService.GROUPS.contains(bloodGroup))){ra.addFlashAttribute("error","Check your required profile fields and try again.");return "redirect:/profile";}u.updateProfile(name.trim(),organization,phone,u.getRole().equals("DONOR")?bloodGroup:null);users.save(u);ra.addFlashAttribute("success","Profile updated.");return "redirect:/profile";}
    @GetMapping("/profile") public String profileRedirect(Authentication auth){return "redirect:/"+me(auth).getRole().toLowerCase(Locale.ROOT)+"/profile";}
}
